// Consume Sygnal's verdict. The receiver already normalized + routed it,
// but recomputing here keeps the workflow self-contained and lets you tune
// routing without redeploying the edge service.
// NOTE: we do NOT re-score. `score` is Sygnal's 0-10 buyer-intent verdict.
const HOT = Number($env.ROUTE_HOT_THRESHOLD || 70);
const WARM = Number($env.ROUTE_WARM_THRESHOLD || 40);

const ROUTES = {
  hot: { action: 'ae_direct', owner: 'ae', slaMinutes: 60, notify: true },
  warm: { action: 'sdr_priority_queue', owner: 'sdr', slaMinutes: 240, notify: false },
  monitor: { action: 'sdr_research_queue', owner: 'sdr', slaMinutes: 1440, notify: false },
  nurture: { action: 'nurture_sequence', owner: 'marketing', slaMinutes: 10080, notify: false },
  archive: { action: 'none', owner: 'none', slaMinutes: 0, notify: false },
};

const signal = $json.signal ?? $json;
const score = Number(signal.score ?? 0);
const priority = Math.max(0, Math.min(100, Math.round(score * 10)));
const bucket = priority >= HOT ? 'hot' : priority >= WARM ? 'warm' : priority >= 20 ? 'monitor' : 'archive';
const route = ROUTES[bucket];
const competitors = signal.competitors ?? [];
const play = competitors.length > 0 ? 'competitive' : 'standard';

return [{
  json: {
    ...signal,
    priority,
    bucket,
    play,
    action: route.action,
    owner: route.owner,
    sla_minutes: route.slaMinutes,
    notify: route.notify,
    received_at: new Date().toISOString(),
  },
}];

parameters.jsonBody:
={{ JSON.stringify({ text: `:rotating_light: HOT ${$json.play} signal (score ${$json.score}/10, icp ${$json.icp_score}, priority ${$json.priority})
source: ${$json.source_label}${($json.competitors||[]).length ? ' · competitor: ' + $json.competitors[0] : ''}
${$json.title}
${$json.url}
${$json.suggested_action}` }) }}
